ee:message.ee:set-payload:
%dw 2.0
output application/json
var fault = payload.Envelope.Body.Fault
---
if(fault != null){
    "code": "ERROR",
    "fault": fault.faultstring
}else{
    "code": "ERROR",
    "fault": payload.Envelope.Body.Set_OperationResponse.Error
}

%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns urn urn:toatech:InboundInterface:1.0
---
soapenv#Envelope: {
    soapenv#Header: {},
    soapenv#Body: {
        urn#inbound_interface_request: {
            user: {
                now: vars.myTime2,
                login: "d84e890edec6c5138c007e487f6bab8a3d92be53",
                company: p('eta-inbound.company'),
                auth_string: vars.shaAuth
            },
            head: {
                processing_mode: "appointment_only",
                upload_type: "incremental",
                date: now() >> "America/Bogota",
                allow_change_date: "yes",
                appointment: {
                    keys: {
                        field: "appt_number"
                    }
                },
                inventory: {
                    keys: {
                        field: "invsn"
                    },
                    upload_type: "incremental"
                },
                properties_mode: "update"
            },
            data: {
                commands: {
                    command: {
                        date: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Appointment.date,
                        'type': "update_appointment",
                        appointment: {
                            appt_number: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Order.id,
                            time_slot: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Appointment.timeSlot,
                            duration: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Appointment.duration,
                            properties: {
                                (property: {
                                    label: "XA_Action_Type",
                                    value: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Order.actionType
                                }) if (payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Order.actionType != null),
                                (property: {
                                    label: "XA_UEN",
                                    value: payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Customer.uen
                                }) if (payload.UpdateScheduleRequest.Input.UpdateScheduleInput.Payload.Customer.uen != null)
                            }
                        }
                    }
                }
            }
        }
    }
}

%dw 2.0
output application/json
var status = payload.Envelope.Body.inbound_interface_response.data.commands.command.appointment.report.message.result
---
{
	("Report": {
		"appointmentId": payload.Envelope.Body.inbound_interface_response.data.commands.command.appointment.aid
	}) if (status == 'success'),
	"Result":{
		"status": if (status == 'success') "PASS" else "FAIL",
		"code": payload.Envelope.Body.inbound_interface_response.data.commands.command.appointment.report.message.result,
		"description": payload.Envelope.Body.inbound_interface_response.data.commands.command.appointment.report.message.description
	}
}
